export const galHiamHymns = galHiamTitles.map(([number, title], index) => ({
  id: `gal-hiam-${index + 1}`,
  number,
  title,
  language: /\p{Script=Myanmar}/u.test(title) ? 'my' : 'ctd',
  lyrics: galHiamLyricsByNumber[`${number}:${title}`] ?? galHiamLyricsByNumber[number],
}));
